styles:
/* Thiết lập khung chứa chính: Tự động co giãn 100% */
        .rog-article-wrapper {
            background-color: #000000;
            color: #FFFFFF;
            font-family: 'Roboto Condensed', sans-serif;
            line-height: 1.6;
            width: 100%;
            box-sizing: border-box; /* Đảm bảo padding không làm vỡ khung */
            padding: 20px;
            overflow: hidden; /* Ngăn nội dung tràn ra ngoài */
        }

        /* Định dạng tiêu đề */
        .rog-article-wrapper h2 {
            color: #FFFFFF !important;
            font-family: 'Roboto Condensed', sans-serif !important;
            text-transform: uppercase;
            font-weight: 700;
            font-size: 1.8em;
            margin-top: 40px;
            margin-bottom: 20px;
            border-left: 5px solid #cc0000;
            padding-left: 15px;
            line-height: 1.2;
        }

        /* Định dạng đoạn văn */
        .rog-article-wrapper p {
            color: #FFFFFF !important;
            margin-bottom: 20px;
            font-size: 1.1em;
        }

        /* Định dạng Link */
        .rog-article-wrapper a {
            color: #ff3333 !important;
            text-decoration: none;
            font-weight: bold;
            transition: color 0.2s;
        }
        .rog-article-wrapper a:hover {
            color: #ff0000 !important;
            text-decoration: underline;
        }

        /* Xử lý ẢNH và VIDEO: Quan trọng để không bị vỡ giao diện */
        .rog-article-wrapper img, 
        .rog-article-wrapper video {
            max-width: 100% !important; /* Bắt buộc ảnh/video không vượt quá khung */
            height: auto !important; /* Giữ tỷ lệ khung hình */
            display: block;
            margin: 25px auto;
            border-radius: 4px;
        }

        /* Highlight text nếu cần */
        .rog-article-wrapper .highlight {
            color: #ffffff;
            font-weight: bold;
        }
